// Written by hand; everything else in this directory is generated by
// blog/blog-parser.c and committed. See blog/README.md.

export type BlogMeta = {
  /** "entry_01" — the entry's identity, and its route: /blog/entry_01 */
  id: string;
  /** Display only. Retitling an entry never moves its URL. */
  title: string;
  /** DD-MM-YYYY, exactly as written in the entry header. */
  date: string;
  /** The filename shown in the ls -la listing, e.g. "entry_01.md". */
  label: string;
};
